gold_sql:
WITH ranked AS (
 SELECT state_name, district_name, value,
 ROW_NUMBER() OVER (PARTITION BY state_name ORDER BY value DESC, district_name) AS rn
 FROM nfhs5_district_indicators WHERE indicator_label = 'Population living in households with electricity (%)'
 AND quality_flag = 'reported'
) SELECT state_name, district_name, value FROM ranked WHERE rn = 1 ORDER BY state_name;

SELECT state_name, AVG(value) AS avg_women_literacy_percent
 FROM nfhs5_district_indicators WHERE indicator_label = 'Women (age 15-49) who are literate4 (%)'
 AND quality_flag = 'reported' GROUP BY state_name ORDER BY avg_women_literacy_percent DESC;

SELECT state_name, district_name, value_raw, quality_flag FROM nfhs5_district_indicators
 WHERE indicator_label = 'Children under 5 years who are stunted (height-for-age)18 (%)'
 AND quality_flag = 'missing_or_unparseable' ORDER BY state_name, district_name;

SELECT state_name, district_name, value FROM nfhs5_district_indicators
 WHERE indicator_label = 'Population living in households that use an improved sanitation facility2 (%)'
 AND quality_flag = 'reported' ORDER BY value ASC LIMIT 5;

SELECT state_name, AVG(value) AS avg_clean_fuel_percent FROM nfhs5_district_indicators
 WHERE indicator_label = 'Households using clean fuel for cooking3 (%)'
 AND quality_flag = 'reported' GROUP BY state_name ORDER BY avg_clean_fuel_percent DESC;

SELECT state_name, district_name, value FROM nfhs5_district_indicators
 WHERE indicator_label = 'Households with any usual member covered under a health insurance/financing scheme (%)'
 AND quality_flag = 'reported' AND value < 25 ORDER BY value ASC;

SELECT state_name, district_name, sample_women_15_49 FROM nfhs5_district_indicators
 WHERE indicator_label = 'Women (age 15-49) who are literate4 (%)'
 AND sample_women_15_49 < 500 ORDER BY sample_women_15_49;

SELECT state_name, AVG(value) AS avg_child_underweight_percent FROM nfhs5_district_indicators
 WHERE indicator_label = 'Children under 5 years who are underweight (weight-for-age)18 (%)'
 AND quality_flag = 'reported' GROUP BY state_name ORDER BY avg_child_underweight_percent DESC;
